(function () {
'use strict';
var Utils = window.Utils;
var HttpApi = window.HttpApi;
var state = {
pageIndex: 1,
pageSize: 20,
keyword: '',
tag: 'all',
minPrice: '',
maxPrice: '',
sortBy: 'default',
sortOrder: 'desc',
loading: false,
hasMore: false,
total: 0
};
var grid;
var moreBtn;
var totalEl;
function params() {
var data = {
pageIndex: state.pageIndex,
pageSize: state.pageSize,
keyword: state.keyword,
sortBy: state.sortBy,
sortOrder: state.sortOrder
};
if (state.tag === 'hot') data.onlyHot = true;
else if (state.tag !== 'all') data.tag = state.tag;
if (state.minPrice !== '') data.minPrice = state.minPrice;
if (state.maxPrice !== '') data.maxPrice = state.maxPrice;
return data;
}
function render(list, reset) {
if (reset) grid.innerHTML = '';
if (!list.length && reset) {
grid.innerHTML = Utils.emptyHtml('没有找到符合条件的车型', '<button type="button" class="btn btn-outline btn-sm" data-reset>重置筛选</button>');
return;
}
grid.insertAdjacentHTML('beforeend', list.map(function (g) { return Utils.goodsCardHtml(g); }).join(''));
Utils.syncActionStates(grid);
}
function load(reset) {
if (state.loading) return;
state.loading = true;
if (reset) {
state.pageIndex = 1;
grid.innerHTML = Utils.skeletonHtml(8);
moreBtn.hidden = true;
}
HttpApi.goods.list(params()).then(function (res) {
state.loading = false;
var rows = (res && res.rows) || [];
state.total = Utils.num(res && (res.total !== undefined ? res.total : res.count), rows.length);
state.hasMore = !!(res && res.hasMore);
if (totalEl) totalEl.textContent = String(state.total);
render(rows, reset);
if (state.hasMore) {
state.pageIndex += 1;
moreBtn.hidden = false;
} else {
moreBtn.hidden = true;
}
if (!rows.length && !reset) {
moreBtn.textContent = '没有更多了';
moreBtn.disabled = true;
}
});
}
function syncCompareCount() {
var el = document.getElementById('shop-compare-count');
if (el) el.textContent = String(Utils.compare.count());
}
function resetFilters() {
state.tag = 'all';
state.keyword = '';
state.minPrice = '';
state.maxPrice = '';
state.sortBy = 'default';
state.sortOrder = 'desc';
Utils.qsa('#shop-tags .chip').forEach(function (btn) {
btn.classList.toggle('is-active', btn.getAttribute('data-tag') === 'all');
});
Utils.qsa('#shop-sort button').forEach(function (btn) {
btn.classList.toggle('is-active', btn.getAttribute('data-sort') === 'default');
});
document.getElementById('shop-keyword').value = '';
document.getElementById('shop-min-price').value = '';
document.getElementById('shop-max-price').value = '';
load(true);
}
function init() {
grid = document.getElementById('shop-grid');
moreBtn = document.getElementById('shop-more');
totalEl = document.getElementById('shop-total');
if (!grid || !moreBtn) return;
Utils.bindCardActions();
syncCompareCount();
var query = Utils.queryAll();
if (query.keyword) {
state.keyword = query.keyword;
document.getElementById('shop-keyword').value = query.keyword;
}
if (query.tag) state.tag = query.tag;
var form = document.getElementById('shop-search');
Utils.on(form, 'submit', function (e) {
e.preventDefault();
state.keyword = document.getElementById('shop-keyword').value.trim();
Utils.track('search_exec', { keyword: state.keyword, from: 'shop' });
load(true);
});
Utils.delegate(document.getElementById('shop-tags'), '.chip', 'click', function () {
state.tag = this.getAttribute('data-tag') || 'all';
Utils.qsa('#shop-tags .chip').forEach(function (btn) { btn.classList.remove('is-active'); });
this.classList.add('is-active');
Utils.track('shop_filter_change', { tag: state.tag });
load(true);
});
Utils.on(document.getElementById('shop-apply-price'), 'click', function () {
var min = document.getElementById('shop-min-price').value;
var max = document.getElementById('shop-max-price').value;
state.minPrice = min === '' ? '' : Math.max(0, Utils.num(min, 0));
state.maxPrice = max === '' ? '' : Math.max(0, Utils.num(max, 0));
load(true);
});
Utils.delegate(document.getElementById('shop-sort'), 'button', 'click', function () {
state.sortBy = this.getAttribute('data-sort') || 'default';
state.sortOrder = this.getAttribute('data-order') || 'desc';
Utils.qsa('#shop-sort button').forEach(function (btn) { btn.classList.remove('is-active'); });
this.classList.add('is-active');
Utils.track('shop_sort_change', { sortBy: state.sortBy, sortOrder: state.sortOrder });
load(true);
});
Utils.on(moreBtn, 'click', function () {
moreBtn.textContent = '加载中…';
load(false);
moreBtn.textContent = '加载更多';
});
Utils.on(grid, 'click', function (e) {
if (e.target.closest('[data-reset]')) resetFilters();
});
Utils.on(window, 'pageshow', syncCompareCount);
load(true);
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', init);
} else {
init();
}
})();
